def seed_application_statuses(apps, schema_editor):
    ApplicationStatus = apps.get_model("admissions", "ApplicationStatus")
    ApplicationStatusTransition = apps.get_model(
        "admissions",
        "ApplicationStatusTransition",
    )
    database = schema_editor.connection.alias
    statuses = {}
    for order, (code, name) in enumerate(STATUSES):
        status, _created = ApplicationStatus.objects.using(database).get_or_create(
            code=code,
            defaults={"name": name, "sort_order": order},
        )
        statuses[code] = status

    ApplicationStatusTransition.objects.using(database).bulk_create(
        [
            ApplicationStatusTransition(
                from_status=statuses[from_code],
                to_status=statuses[to_code],
            )
            for from_code, to_codes in TRANSITIONS.items()
            for to_code in to_codes
        ]
    )


